-- Dynamic site header (one document per language).
--
-- The public site (new_fly_cham) renders its top header from this document and
-- the cms2 admin edits it; both go through the cms backend routes
-- /api/public/get-header and /api/public/update-header. Shape + limits are
-- validated server-side in cms/src/lib/site-header.ts (HeaderDocument).
--
--   data     jsonb   the HeaderDocument (schemaVersion 1)
--   version  integer optimistic-concurrency counter (update ... where version = ?)
--
-- RLS: readable by anon + authenticated; INSERT/UPDATE for admins only
-- (public.is_admin()); no DELETE policy.
--
-- Seed: both rows (en, ar) reproduce today's static header exactly. Generated
-- from default-header.json — do not hand-edit the JSON below.

CREATE TABLE IF NOT EXISTS public.site_header (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  lang text NOT NULL UNIQUE CHECK (lang IN ('en', 'ar')),
  data jsonb NOT NULL CHECK (jsonb_typeof(data) = 'object'),
  version integer NOT NULL DEFAULT 1 CHECK (version >= 1),
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid NULL REFERENCES auth.users(id) ON DELETE SET NULL
);

COMMENT ON TABLE public.site_header IS
  'Dynamic site header document per language (HeaderDocument, see cms/src/lib/site-header.ts).';
COMMENT ON COLUMN public.site_header.version IS
  'Optimistic concurrency counter; bumped by every successful update.';

GRANT SELECT ON public.site_header TO anon;
GRANT SELECT, INSERT, UPDATE ON public.site_header TO authenticated;
GRANT ALL ON public.site_header TO service_role;
ALTER TABLE public.site_header ENABLE ROW LEVEL SECURITY;

-- Keep updated_at current and stamp the editor (auth.uid() is NULL for
-- migrations / service-role writes).
CREATE OR REPLACE FUNCTION public.site_header_touch()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.updated_at = now();
  NEW.updated_by = auth.uid();
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.site_header_touch() FROM PUBLIC;

DROP TRIGGER IF EXISTS site_header_touch ON public.site_header;
CREATE TRIGGER site_header_touch
  BEFORE INSERT OR UPDATE ON public.site_header
  FOR EACH ROW EXECUTE FUNCTION public.site_header_touch();

-- policies
DROP POLICY IF EXISTS "Site header is public" ON public.site_header;
CREATE POLICY "Site header is public" ON public.site_header
  FOR SELECT TO anon, authenticated
  USING (true);

DROP POLICY IF EXISTS "Admins insert site header" ON public.site_header;
CREATE POLICY "Admins insert site header" ON public.site_header
  FOR INSERT TO authenticated
  WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS "Admins update site header" ON public.site_header;
CREATE POLICY "Admins update site header" ON public.site_header
  FOR UPDATE TO authenticated
  USING (public.is_admin()) WITH CHECK (public.is_admin());

